mapper.select:
SELECT DISTINCT msm.user_id
FROM weekly_saving_missions wsm
         JOIN monthly_saving_missions msm ON msm.id = wsm.monthly_saving_mission_id
         JOIN users u ON u.id = msm.user_id
WHERE msm.target_year_month = #{targetYearMonth}
  AND wsm.week_number = #{weekNumber}
  AND wsm.period_end_date < #{runDate}
  AND u.is_deleted = 0
  AND (
        wsm.status = 'PENDING'
        OR (wsm.status = 'SUCCESS' AND wsm.wallet_ledger_id IS NULL)
      )
ORDER BY msm.user_id
